from curriculum.harness import (
    AgentRunner,
    ModelTurn,
    ScriptedModel,
    Tool,
    ToolCall,
    ToolRegistry,
)
from curriculum.lessons.common import lesson_trace, print_run


def build_demo() -> tuple[AgentRunner, object]:
    registry = ToolRegistry()
    registry.register(
        Tool(
            name="echo",
            description="Return the supplied text.",
            parameters={
                "type": "object",
                "additionalProperties": False,
                "required": ["text"],
                "properties": {"text": {"type": "string"}},
            },
            handler=lambda args: {"echo": args["text"]},
        )
    )
    model = ScriptedModel(
        [
            ModelTurn(
                tool_calls=(
                    ToolCall(id="call-001", name="echo", arguments={"text": "hello"}),
                )
            ),
            ModelTurn(content="The echo tool returned hello.", stop=True),
        ]
    )
    trace = lesson_trace("s03-tool-dispatch")
    return AgentRunner(model=model, tools=registry, trace=trace), trace


def main() -> None:
    runner, trace = build_demo()
    result = runner.run("Use the echo tool, then report its result.")
    print_run(result.final_text, trace)


if __name__ == "__main__":
    main()

from curriculum.harness import (
    AgentRunner,
    ContextBudget,
    ModelTurn,
    ScriptedModel,
    Tool,
    ToolCall,
    ToolRegistry,
)
from curriculum.lessons.common import lesson_trace, print_run


def build_demo() -> tuple[AgentRunner, object]:
    registry = ToolRegistry()
    registry.register(
        Tool(
            name="large_result",
            description="Return a deliberately oversized synthetic payload.",
            parameters={
                "type": "object",
                "additionalProperties": False,
                "properties": {},
            },
            handler=lambda args: {"content": "context-data-" * 80},
        )
    )
    model = ScriptedModel(
        [
            ModelTurn(
                tool_calls=(
                    ToolCall(id="call-large", name="large_result", arguments={}),
                )
            ),
            ModelTurn(content="The harness truncated the oversized result.", stop=True),
        ]
    )
    trace = lesson_trace("s06-context-budget")
    return (
        AgentRunner(
            model=model,
            tools=registry,
            trace=trace,
            system_prompt="Keep tool output bounded. " * 8,
            budget=ContextBudget(max_input_chars=300, max_tool_output_chars=180),
        ),
        trace,
    )


def main() -> None:
    runner, trace = build_demo()
    result = runner.run("Fetch the large result, then explain the budget behavior.")
    print_run(result.final_text, trace)


if __name__ == "__main__":
    main()

overview_content.en:
# Reference Harness

Reference Harness is the project's minimal teaching and controlled-experiment baseline, not a product intended to compete with Codex, Claude Code, or another production agent. It keeps the scripted model double, agent loop, tool registry, workspace path boundary, and Trace recorder in a dependency-free Python implementation.

- Current coverage: Tier C, project-owned controlled baseline;
- Research role: validate the contract between Registry, Experiment, Result, Trace, and web replay;
- Model boundary: Scripted Model returns predeclared turns and says nothing about real model capability;
- Safety boundary: Workspace constrains path resolution but is not an operating-system sandbox;
- Reproducibility: pinned prompt and fixture digests, fixed timestamps, two repetitions, and a normalized trace fingerprint.

It answers whether the experiment infrastructure itself works. Native adapters can then connect observable behavior from real agents to the same evidence chain.
